INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Tolemiere ich hier unnötige Arbeit?', 2, '[{"text": "Nein", "correct": true, "because": "Verschwendung eliminieren ist zentral"}, {"text": "Ja", "correct": false, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sorgt für Kundennutzen?', 3, '[{"text": "Wert maximieren", "correct": true, "because": "Kundenwert im Mittelpunkt"}, {"text": "Verschwendung eliminieren", "correct": false, "because": "Effizienz steigern"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Geschwindigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Leitlinien fördern Effizienz?', 5, '[{"text": "Verschwendung eliminieren", "correct": true, "because": "Unnötiges reduzieren"}, {"text": "Schnelle Lieferung", "correct": true, "because": "Zeit sparen"}, {"text": "Überflüssige Features", "correct": false, "because": "Widerspricht Lean"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schnelle Lieferung ist zentral. b) Wert maximieren ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wert maximieren essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Prinzipien?', 4, '[{"text": "Verschwendung eliminieren", "correct": false, "because": "Kernprinzip"}, {"text": "Wert maximieren", "correct": false, "because": "Kundenfokus"}, {"text": "Langsame Prozesse", "correct": true, "because": "Schnelligkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier Verschwendung akzeptiere?', 2, '[{"text": "Nein", "correct": true, "because": "Verschwendung wird eliminiert"}, {"text": "Ja", "correct": false, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für schnelle Ergebnisse?', 3, '[{"text": "Schnelle Lieferung", "correct": true, "because": "Zeit optimieren"}, {"text": "Wert maximieren", "correct": false, "because": "Kundenwert zählt"}, {"text": "Verschwendung eliminieren", "correct": false, "because": "Effizienz steigern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundsätze unterstützen schlanke Entwicklung?', 5, '[{"text": "Wert maximieren", "correct": true, "because": "Nutzen im Fokus"}, {"text": "Verschwendung eliminieren", "correct": true, "because": "Effizienz erhöhen"}, {"text": "Komplexe Features", "correct": false, "because": "Minimalismus zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Verschwendung wird reduziert. b) Lieferung ist langsam. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schnelle Lieferung zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Schnelle Lieferung", "correct": false, "because": "Effizienz fördern"}, {"text": "Wert maximieren", "correct": false, "because": "Kundenfokus"}, {"text": "Unnötige Arbeit", "correct": true, "because": "Verschwendung eliminieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Wert maximieren hier unwichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Kundenwert im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien verbessern die Effizienz?', 4, '[{"text": "Verschwendung eliminieren", "correct": true, "because": "Unnötiges entfernen"}, {"text": "Schnelle Lieferung", "correct": true, "because": "Zeit sparen"}, {"text": "Langsame Prozesse", "correct": false, "because": "Effizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier langsam liefere. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schnelle Lieferung ist Prinzip"}, {"text": "Ja", "correct": false, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für den Kunden?', 3, '[{"text": "Wert maximieren", "correct": true, "because": "Kundennutzen steigern"}, {"text": "Langsame Lieferung", "correct": false, "because": "Schnelligkeit zählt"}, {"text": "Verschwendung akzeptieren", "correct": false, "because": "Effizienz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschwendung wird minimiert. b) Wert ist zweitrangig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wert ist zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Prinzipien?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Verschwendung eliminieren"}, {"text": "Kundenfokus", "correct": true, "because": "Wert maximieren"}, {"text": "Langsame Zyklen", "correct": false, "because": "Schnelligkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Schnelle Lieferung", "correct": false, "because": "Effizienz fördern"}, {"text": "Wert maximieren", "correct": false, "because": "Kundenfokus"}, {"text": "Unnötige Features", "correct": true, "because": "Verschwendung vermeiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist schnelle Lieferung hier nebensächlich?', 3, '[{"text": "Nein", "correct": true, "because": "Kernprinzip für Effizienz"}, {"text": "Ja", "correct": false, "because": "Schnelligkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier Wert ignoriere?', 2, '[{"text": "Nein", "correct": true, "because": "Wert maximieren ist zentral"}, {"text": "Ja", "correct": false, "because": "Kundenfokus nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für weniger Verschwendung?', 4, '[{"text": "Verschwendung eliminieren", "correct": true, "because": "Unnötiges reduzieren"}, {"text": "Langsame Prozesse", "correct": false, "because": "Schnelligkeit zählt"}, {"text": "Wert ignorieren", "correct": false, "because": "Kundenfokus nötig"}]');
